    assertEquals(0, new File(filePath).length());
    assertEquals(true, overflowFileIO.getOverflowIOForMerge() != null);
    // test swithc merge to work
    overflowFileIO.switchFileIOMergeToWorking();
    // check merge file
    assertEquals(false, mergeFile.exists());
